function salvar_foto_oferta($arquivo,&$erros){
 if(empty($arquivo['name']))return '';
 if(($arquivo['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK){$erros[]='Não foi possível receber a foto.';return '';}
 $mime=(new finfo(FILEINFO_MIME_TYPE))->file($arquivo['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
 if(!isset($ext[$mime])){$erros[]='A foto deve ser JPG, PNG ou WebP.';return '';}
 $dir=__DIR__.'/../assets/uploads/offerings';if(!is_dir($dir))mkdir($dir,0755,true);$nome=bin2hex(random_bytes(16)).'.'.$ext[$mime];
 return move_uploaded_file($arquivo['tmp_name'],$dir.'/'.$nome)?'/assets/uploads/offerings/'.$nome:'';
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!validar_csrf($_POST['csrf_token']??''))$erros[]='A sessão expirou. Atualize a página.';$acao=$_POST['acao']??'';
 if(!$erros&&$acao==='categoria_criar'){$nome=normalizar_rotulo($_POST['categoria_nome']??'');if(mb_strlen($nome)<2)$erros[]='Informe uma categoria válida.';else{$stmt=$mysqli->prepare('INSERT IGNORE INTO categorias_profissionais(profissional_id,nome) VALUES(?,?)');$stmt->bind_param('is',$perfil['id'],$nome);$stmt->execute();mensagem_sucesso('Categoria disponível para seus serviços.');redirecionar('/dashboard/ofertas.php');}}
 if(!$erros&&$acao==='suspender_imagem'){$id=(int)($_POST['id']??0);$stmt=$mysqli->prepare('UPDATE ofertas_profissionais SET ativo=0 WHERE id=? AND profissional_id=?');$stmt->bind_param('ii',$id,$perfil['id']);$stmt->execute();header('Content-Type: application/json');echo json_encode(['ok'=>true]);exit;}
 if(!$erros&&in_array($acao,['alternar','excluir'],true)){$id=(int)($_POST['id']??0);$sql=$acao==='excluir'?'DELETE FROM ofertas_profissionais WHERE id=? AND profissional_id=?':'UPDATE ofertas_profissionais SET ativo=NOT ativo WHERE id=? AND profissional_id=?';$stmt=$mysqli->prepare($sql);$stmt->bind_param('ii',$id,$perfil['id']);$stmt->execute();mensagem_sucesso($acao==='excluir'?'Serviço removido.':'Disponibilidade atualizada.');redirecionar('/dashboard/ofertas.php');}
 if(!$erros&&in_array($acao,['criar','editar'],true)){
  $id=(int)($_POST['id']??0);$nome=normalizar_rotulo($_POST['nome']??'');$categoria_id=(int)($_POST['categoria_id']??0);$subcategoria=normalizar_rotulo($_POST['subcategoria']??'');$publico=$_POST['publico']??'geral';$descricao=trim($_POST['descricao']??'');$preco=str_replace(',','.',trim($_POST['preco_inicial']??''));$unidade=trim($_POST['unidade_preco']??'por serviço');$imagem=trim($_POST['imagem_url']??'');
  $stmt=$mysqli->prepare('SELECT nome FROM categorias_profissionais WHERE id=? AND profissional_id=?');$stmt->bind_param('ii',$categoria_id,$perfil['id']);$stmt->execute();$categoria=$stmt->get_result()->fetch_assoc()['nome']??'';
  $upload=salvar_foto_oferta($_FILES['imagem']??[],$erros);if($upload)$imagem=$upload;
  if(mb_strlen($nome)<3||!$categoria||mb_strlen($descricao)<10)$erros[]='Preencha nome, categoria e uma descrição detalhada.';
  if(mb_strlen($subcategoria)<2)$erros[]='Informe uma subcategoria.';if(!in_array($publico,['residencial','comercial','industrial','geral'],true))$erros[]='Selecione um público válido.';
  if($preco===''||!is_numeric($preco)||(float)$preco<0)$erros[]='O valor do serviço é obrigatório.';
  if(!$imagem)$erros[]='A foto do serviço é obrigatória.';elseif(!str_starts_with($imagem,'/assets/uploads/')&&!filter_var($imagem,FILTER_VALIDATE_URL))$erros[]='Informe uma foto ou URL válida.';
  if(!$erros){$valor=(float)$preco;if($acao==='criar'){$stmt=$mysqli->prepare('INSERT INTO ofertas_profissionais(profissional_id,nome,categoria,categoria_id,subcategoria,publico,descricao,imagem_url,preco_inicial,unidade_preco) VALUES(?,?,?,?,?,?,?,?,?,?)');$stmt->bind_param('ississssds',$perfil['id'],$nome,$categoria,$categoria_id,$subcategoria,$publico,$descricao,$imagem,$valor,$unidade);}else{$stmt=$mysqli->prepare('UPDATE ofertas_profissionais SET nome=?,categoria=?,categoria_id=?,subcategoria=?,publico=?,descricao=?,imagem_url=?,preco_inicial=?,unidade_preco=? WHERE id=? AND profissional_id=?');$stmt->bind_param('ssissssdsii',$nome,$categoria,$categoria_id,$subcategoria,$publico,$descricao,$imagem,$valor,$unidade,$id,$perfil['id']);}$stmt->execute();mensagem_sucesso($acao==='criar'?'Serviço publicado.':'Serviço atualizado.');redirecionar('/dashboard/ofertas.php');}
 }
}
$stmt=$mysqli->prepare('SELECT * FROM categorias_profissionais WHERE profissional_id=? ORDER BY nome');$stmt->bind_param('i',$perfil['id']);$stmt->execute();$categorias=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$stmt=$mysqli->prepare('SELECT * FROM ofertas_profissionais WHERE profissional_id=? ORDER BY criado_em DESC');$stmt->bind_param('i',$perfil['id']);$stmt->execute();$ofertas=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);require_once __DIR__.'/../includes/header.php';
?>
<div class="container professional-services"><div class="page-heading"><div><h1>Meus Serviços</h1><p>Crie e gerencie os cards exibidos no catálogo e no seu perfil.</p></div><button class="btn" type="button" data-toggle-service-form>+ Cadastrar serviço</button></div><?php exibir_mensagens(); ?><?php if($erros): ?><div class="alerta alerta-erro"><?php echo sanitizar(implode(' ',$erros)); ?></div><?php endif; ?>
<section class="category-manager"><form method="POST"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="categoria_criar"><label for="categoria_nome">Suas categorias</label><div><input id="categoria_nome" name="categoria_nome" placeholder="Ex.: Instalação elétrica" required><button class="btn-small" type="submit">Adicionar categoria</button></div></form><p>Você cria as categorias; elas ficam disponíveis na seleção de cada serviço.</p></section>
<form method="POST" enctype="multipart/form-data" class="service-form creation-form" <?php echo $erros?'':'hidden'; ?>><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="criar"><h2>Novo serviço</h2><div class="form-grid"><div class="form-group"><label>Nome do serviço</label><input name="nome" required></div><div class="form-group"><label>Categoria</label><select name="categoria_id" required><option value="">Selecione</option><?php foreach($categorias as $cat): ?><option value="<?php echo (int)$cat['id']; ?>"><?php echo sanitizar($cat['nome']); ?></option><?php endforeach; ?></select></div><div class="form-group form-span"><label>Descrição</label><textarea name="descricao" rows="4" required></textarea></div><div class="form-group"><label>Valor</label><input name="preco_inicial" inputmode="decimal" placeholder="150,00" required></div><div class="form-group"><label>Forma de cobrança</label><select name="unidade_preco"><option>por serviço</option><option>por hora</option><option>por diária</option><option>por projeto</option></select></div><div class="form-group"><label>Foto do computador</label><input type="file" name="imagem" accept="image/jpeg,image/png,image/webp"></div><div class="form-group"><label>Ou imagem por URL</label><input type="url" name="imagem_url" placeholder="https://..."></div></div><button class="btn" type="submit">Publicar serviço</button></form>
<?php if($ofertas): ?><div class="owned-services-grid"><?php foreach($ofertas as $oferta): ?><article class="owned-service-card <?php echo $oferta['ativo']?'':'is-paused'; ?>"><img src="<?php echo sanitizar($oferta['imagem_url']?:'/assets/img/service-placeholder.svg'); ?>" alt=""><div class="owned-card-body"><div class="card-status-row"><span class="status <?php echo $oferta['ativo']?'status-confirmado':'status-cancelado'; ?>"><?php echo $oferta['ativo']?'Publicado':'Pausado'; ?></span><strong>★ <?php echo number_format((float)$oferta['nota_media'],1,',','.'); ?>/10</strong></div><small><?php echo sanitizar($oferta['categoria']); ?></small><h2><?php echo sanitizar($oferta['nome']); ?></h2><p><?php echo sanitizar($oferta['descricao']); ?></p><div class="price">R$ <?php echo number_format((float)$oferta['preco_inicial'],2,',','.'); ?> <small><?php echo sanitizar($oferta['unidade_preco']); ?></small></div><div class="table-actions"><form method="POST"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="alternar"><input type="hidden" name="id" value="<?php echo (int)$oferta['id']; ?>"><button class="btn-small" type="submit"><?php echo $oferta['ativo']?'Pausar':'Publicar'; ?></button></form><button class="btn-small" type="button" data-edit-card="<?php echo (int)$oferta['id']; ?>">Editar</button><form method="POST" onsubmit="return confirm('Remover este serviço?')"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?php echo (int)$oferta['id']; ?>"><button class="btn-small btn-danger" type="submit">Excluir</button></form></div></div><form id="edit-<?php echo (int)$oferta['id']; ?>" class="card-edit-form" method="POST" enctype="multipart/form-data" hidden><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="editar"><input type="hidden" name="id" value="<?php echo (int)$oferta['id']; ?>"><input name="nome" value="<?php echo sanitizar($oferta['nome']); ?>" required><select name="categoria_id" required><?php foreach($categorias as $cat): ?><option value="<?php echo (int)$cat['id']; ?>" <?php echo (int)$oferta['categoria_id']===(int)$cat['id']?'selected':''; ?>><?php echo sanitizar($cat['nome']); ?></option><?php endforeach; ?></select><textarea name="descricao" required><?php echo sanitizar($oferta['descricao']); ?></textarea><input name="preco_inicial" value="<?php echo sanitizar($oferta['preco_inicial']); ?>" required><select name="unidade_preco"><?php foreach(['por serviço','por hora','por diária','por projeto'] as $u): ?><option <?php echo $oferta['unidade_preco']===$u?'selected':''; ?>><?php echo $u; ?></option><?php endforeach; ?></select><input type="file" name="imagem" accept="image/jpeg,image/png,image/webp"><input type="url" name="imagem_url" value="<?php echo sanitizar($oferta['imagem_url']); ?>"><button class="btn" type="submit">Salvar alterações</button></form></article><?php endforeach; ?></div><?php else: ?><div class="market-empty"><h2>Nenhum serviço publicado</h2><p>Crie uma categoria e publique seu primeiro card.</p></div><?php endif; ?></div>
<script>
const csrf=<?php echo json_encode(token_csrf()); ?>;
const offerMeta=<?php echo json_encode(array_column(array_map(fn($o)=>['id'=>(int)$o['id'],'subcategoria'=>$o['subcategoria']??'','publico'=>$o['publico']??'geral'],$ofertas),null,'id'),JSON_UNESCAPED_UNICODE); ?>;
function classificationFields(form,values={}){if(!form)return;const category=form.querySelector('[name="categoria_id"]');if(!category||form.querySelector('[name="subcategoria"]'))return;const sub=document.createElement('div'),audience=document.createElement('div');sub.className='form-group dynamic-classification';audience.className='form-group dynamic-classification';sub.innerHTML='<label>Subcategoria</label><input name="subcategoria" required placeholder="Ex.: Instalação de disjuntores">';audience.innerHTML='<label>Público</label><select name="publico" required><option value="geral">Geral</option><option value="residencial">Residencial</option><option value="comercial">Comercial</option><option value="industrial">Industrial</option></select>';const anchor=category.closest('.form-group')||category;anchor.after(audience);anchor.after(sub);sub.querySelector('input').value=values.subcategoria||'';audience.querySelector('select').value=values.publico||'geral';}
classificationFields(document.querySelector('.creation-form'));
document.querySelectorAll('.card-edit-form').forEach(form=>{const id=form.querySelector('[name="id"]').value;classificationFields(form,offerMeta[id]);const body=form.previousElementSibling,badge=document.createElement('div');badge.className='service-classification';badge.textContent=(offerMeta[id]?.subcategoria||'Sem subcategoria')+' · '+(offerMeta[id]?.publico||'geral');body.querySelector('h2')?.after(badge);});
document.querySelector('[data-toggle-service-form]')?.addEventListener('click',()=>{const f=document.querySelector('.creation-form');f.hidden=!f.hidden;});
document.querySelectorAll('[data-edit-card]').forEach(b=>b.addEventListener('click',()=>{const f=document.getElementById('edit-'+b.dataset.editCard);f.hidden=!f.hidden;b.textContent=f.hidden?'Editar':'Fechar edição';}));
document.querySelectorAll('.card-edit-form input[name="imagem_url"]').forEach(input=>{input.type='text';input.placeholder='https://... ou /assets/uploads/...';});
document.querySelectorAll('.owned-service-card>img').forEach(img=>img.addEventListener('error',async()=>{const card=img.closest('.owned-service-card'),form=card.querySelector('.card-edit-form'),id=form?.querySelector('[name="id"]')?.value;if(!id||img.dataset.reported)return;img.dataset.reported='1';card.classList.add('is-paused','has-broken-image');const aviso=document.createElement('div');aviso.className='broken-image-warning';aviso.textContent='Foto indisponível. Serviço suspenso até você trocar a imagem.';card.prepend(aviso);img.src='/assets/img/service-placeholder.svg';await fetch('/dashboard/ofertas.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({csrf_token:csrf,acao:'suspender_imagem',id})});}));
</script>
